  deleteProfile(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot>;
  start(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot>;
  stop(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot>;
