const { invoke, listen } = vi.hoisted(() => ({ invoke: vi.fn(), listen: vi.fn() }));
vi.mock("@tauri-apps/api/core", () => ({ invoke }));
vi.mock("@tauri-apps/api/event", () => ({ listen }));
import { createNativeSshForwardHost, NATIVE_SSH_FORWARD_COMMANDS } from "./native-ssh-forward-host";

const context = { desktopInstanceId: "desktop", managerSessionId: "manager", clientEpoch: "10" as const };
describe("native ssh forwarding host", () => {
  beforeEach(() => { invoke.mockReset(); listen.mockReset(); listen.mockResolvedValue(vi.fn()); });
  it("maps exactly the twelve Rust command names", () => {
    expect(NATIVE_SSH_FORWARD_COMMANDS).toEqual({ openClient: "ssh_forward_open_client", activateScope: "ssh_forward_activate_scope", snapshot: "ssh_forward_snapshot", createProfile: "ssh_forward_create_profile", updateProfile: "ssh_forward_update_profile", deleteProfile: "ssh_forward_delete_profile", start: "ssh_forward_start", stop: "ssh_forward_stop", restart: "ssh_forward_restart", listKeys: "ssh_forward_list_keys", approveHost: "ssh_forward_approve_host", purgeScope: "ssh_forward_purge_scope" });
    expect(Object.keys(NATIVE_SSH_FORWARD_COMMANDS)).toHaveLength(12);
  });
  it("does zero Tauri calls for mobile or unknown platforms", () => {
    expect(createNativeSshForwardHost("android")).toBeNull(); expect(createNativeSshForwardHost("ios")).toBeNull(); expect(createNativeSshForwardHost("unknown")).toBeNull();
    expect(invoke).not.toHaveBeenCalled(); expect(listen).not.toHaveBeenCalled();
  });
  it("installs listener before open then sends immediate increasing activations", async () => {
    invoke.mockResolvedValueOnce({ context, activationTokenFloor: "9", activeScopeId: null, scopeGeneration: "0" }).mockResolvedValue({ context, activationToken: "10", scopeId: "a", scopeGeneration: "1", snapshot: null });
    const host = createNativeSshForwardHost("windows")!;
    await host.openClient({ status: "available", ids: ["a"] }); await host.activateScope("a");
    expect(listen).toHaveBeenCalledBefore(invoke); expect(invoke.mock.calls[1]).toEqual(["ssh_forward_activate_scope", { input: { context, activationToken: "10", scopeId: "a" } }]);
  });
  it("dispose only unlistens", async () => { const unlisten = vi.fn(); listen.mockResolvedValue(unlisten); invoke.mockResolvedValue({ context, activationTokenFloor: "0", activeScopeId: null, scopeGeneration: "0" }); const host = createNativeSshForwardHost("linux")!; await host.openClient({ status: "available", ids: [] }); host.dispose(); expect(unlisten).toHaveBeenCalledOnce(); expect(invoke).toHaveBeenCalledTimes(1); });
});

