    return this.listening;
  }
  private handleHint(hint: SshForwardEventHint): void {
    const context = this.context;
    const snapshot = this.snapshotState;
    if (!context || !snapshot || hint.desktopInstanceId !== context.desktopInstanceId || hint.managerSessionId !== context.managerSessionId || hint.clientEpoch !== context.clientEpoch || hint.activationToken !== this.activationToken || hint.scopeId !== this.scopeId) return;
    if (![hint.scopeGeneration, hint.profilesRevision, hint.trustRevision].every(isCounter)) return;
    const stale = wireCounterToBigInt(hint.scopeGeneration) < wireCounterToBigInt(snapshot.scopeGeneration) || wireCounterToBigInt(hint.profilesRevision) < wireCounterToBigInt(snapshot.profilesRevision) || wireCounterToBigInt(hint.trustRevision) < wireCounterToBigInt(snapshot.trustRevision);
    if (stale) return;
    for (const listener of this.listeners) listener({ type: "changed", hint });
    this.requestHintSnapshot();
  }
  private requestHintSnapshot(): void {
    if (this.snapshotInFlight) { this.snapshotTrailing = true; return; }
    this.snapshotInFlight = true;
    void this.snapshot().catch(() => {}).finally(() => { this.snapshotInFlight = false; if (this.snapshotTrailing) { this.snapshotTrailing = false; this.requestHintSnapshot(); } });
  }
}

/** SSH forwarding native capability has currently shipped only on Windows. */
export function createNativeSshForwardHost(platform: string, enabled = true): NativeSshForwardHost | null { return enabled && platform === "windows" ? new NativeSshForwardHost() : null; }
